 private fun go(task:()->String,done:(String)->Unit){
  val generation=try{currentSession()?.generation?:authSession.generationSnapshot()}catch(e:Exception){showRequestError(e);return}
  ex.execute{val previous=requestTicketLocal.get();try{authSession.assertCurrentGeneration(generation);requestTicketLocal.set(generation);val value=task();authSession.assertCurrentGeneration(generation);requestTicketLocal.remove();runOnUiThread{try{authSession.assertCurrentGeneration(generation);done(value)}catch(e:Exception){showRequestError(e)}}}catch(e:Exception){requestTicketLocal.remove();runOnUiThread{showRequestError(e)}}finally{if(previous!=null)requestTicketLocal.set(previous)}}
 }
 private fun requestText(url:String,method:String,data:JSONObject?,prefer:String?,session:CenaAuthSession?,apiKey:String?,expectedGeneration:Long?,apiErrors:Boolean=false):String{
  if(expectedGeneration!=null)authSession.assertCurrentGeneration(expectedGeneration)
  if(session!=null&&expectedGeneration!=null&&session.generation!=expectedGeneration)throw CenaSessionExpiredException()
  var token=session?.let{authSession.accessTokenForRequest(it.generation)}
  if(session!=null&&token.isNullOrBlank())throw CenaSessionExpiredException()
  var refreshed=false
  while(true){
   if(expectedGeneration!=null)authSession.assertCurrentGeneration(expectedGeneration)
   if(session!=null)authSession.assertCurrentGeneration(session.generation)
   val connection=URL(url).openConnection() as HttpURLConnection
   val status:Int;val response:String
   try{
    connection.requestMethod=method;connection.connectTimeout=9000;connection.readTimeout=12000
    apiKey?.let{connection.setRequestProperty("apikey",it)}
    connection.setRequestProperty("Content-Type","application/json")
    if(prefer!=null)connection.setRequestProperty("Prefer",prefer)
    val bearer=token?:apiKey
    if(!bearer.isNullOrBlank())connection.setRequestProperty("Authorization","Bearer $bearer")
    if(data!=null){connection.doOutput=true;connection.outputStream.use{it.write(data.toString().toByteArray())}}
    status=connection.responseCode
    val stream=if(status<400)connection.inputStream else connection.errorStream
    response=stream?.bufferedReader()?.use{it.readText()}?:""
   }finally{connection.disconnect()}
   if(status==401&&session!=null){
    if(refreshed){authSession.signOutIfCurrent(session.generation);throw CenaSessionExpiredException()}
    token=authSession.refreshAfterUnauthorized(token?:throw CenaSessionExpiredException(),session.generation);refreshed=true;continue
   }
   if(expectedGeneration!=null)authSession.assertCurrentGeneration(expectedGeneration)
   if(session!=null)authSession.assertCurrentGeneration(session.generation)
   if(status>=400){if(apiErrors)throw CenaApiHttpException(status,response);throw Exception(response)}
   return response
  }
 }
 private fun req(path:String,method:String="GET",data:JSONObject?=null,prefer:String?=null,useSession:Boolean=true):String{
  val expected=requestTicketLocal.get();if(expected!=null)authSession.assertCurrentGeneration(expected)
  val session=if(useSession)currentSession()else null
  return requestText(BuildConfig.SUPABASE_URL.trimEnd('/')+path,method,data,prefer,session,BuildConfig.SUPABASE_KEY,expected)
 }
 private fun apiReq(path:String,method:String="GET",data:JSONObject?=null):String{
  val expected=requestTicketLocal.get();if(expected!=null)authSession.assertCurrentGeneration(expected)
  val session=currentSession()?:throw CenaSessionExpiredException()
  return requestText(BuildConfig.CENA_API_URL.trimEnd('/')+path,method,data,null,session,null,expected,true)
 } private fun restoreBag(){
  bag.clear();val session=currentSession();val savedOwner=pref.getString("bag_user_id",null);val owner=session?.userId?:"guest"
  if(session==null&&savedOwner!=null&&savedOwner!="guest")return
