 }private fun persistBag(){val a=JSONArray();for(line in bag)a.put(JSONObject().put("restaurant",line.restaurant).put("meal",line.meal).put("quantity",line.quantity));val owner=currentUserId()?:pref.getString("bag_user_id",null)?.takeIf{it.isNotBlank()}?:"guest";pref.edit().putString("bag_json",a.toString()).putString("bag_user_id",owner).apply()} private fun validCheckoutUrl(value:String):Boolean{try{val uri=java.net.URI(value);return uri.scheme=="https"&&uri.host.equals("checkout.stripe.com",true)&&uri.userInfo==null}catch(_:Exception){return false}}
 private val recoverableCheckoutCodes=setOf("promo_unavailable","pickup_unavailable","item_unavailable","restaurant_unavailable","curbside_unavailable","order_total_too_low")
 private fun checkoutRejectionMessage(code:String)=when(code){"promo_unavailable"->"That discount code is unavailable. Check it or continue without it.";"pickup_unavailable"->"That pickup time is no longer available. Choose another time.";"item_unavailable"->"A meal kit in your bag is unavailable for that pickup time. Update your bag or choose another time.";"curbside_unavailable"->"Curbside is unavailable. Choose counter pickup to continue.";"restaurant_unavailable"->"This restaurant isn’t taking online orders right now.";"order_total_too_low"->"The order total is too low for online payment. Update your bag or remove the discount code.";else->"Your bag is saved. Review your pickup details and try again."}
 private fun showCheckoutRecovery(code:String,message:String,promoCode:String?,owner:String,screen:View){if(body!==screen||currentUserId()!=owner)return;val dialog=AlertDialog.Builder(this).setMessage("$message\n\nYour bag is saved. No payment was started.").setNegativeButton("Keep bag",null);when(code){"promo_unavailable"->{dialog.setTitle("Discount code unavailable").setNegativeButton("Edit code"){_,_->checkout()}.setPositiveButton("Review without code"){_,_->applyPromoAndContinue(null)}};"pickup_unavailable"->{dialog.setTitle("Pickup time unavailable").setNegativeButton("Review bag"){_,_->bagScreen()}.setPositiveButton("Choose another time"){_,_->slot=null;activePromoCode=null;expectedAmountCents=null;loadSlots()}};"item_unavailable"->{dialog.setTitle("Meal kit unavailable").setPositiveButton("Review bag"){_,_->bagScreen()}};"curbside_unavailable"->{dialog.setTitle("Curbside unavailable").setPositiveButton("Switch to counter pickup"){_,_->curbsideForCheckout=false;curbMake="";curbModel="";curbColor="";activePromoCode=null;expectedAmountCents=null;checkout()}};"restaurant_unavailable"->{dialog.setTitle("Restaurant unavailable").setPositiveButton("Explore other kitchens"){_,_->slot=null;activePromoCode=null;expectedAmountCents=null;catalog()}};"order_total_too_low"->{dialog.setTitle("Order total too low");if(!promoCode.isNullOrBlank())dialog.setNegativeButton("Edit bag"){_,_->bagScreen()}.setPositiveButton("Review without code"){_,_->checkout();applyPromoAndContinue(null)}else dialog.setPositiveButton("Update bag"){_,_->bagScreen()}}};dialog.show()}
 private fun clearPaymentMarkers(){pref.edit().remove("pending_checkout_order").remove("pending_checkout_url").remove("pending_checkout_user_id").remove("checkout_request").remove("checkout_idempotency_key").remove("checkout_user_id").commit()}
 private fun finishPaidPayment(){bag.clear();persistBag();clearPaymentMarkers();paidNotice="Payment confirmed. Your order is in My orders.";updateBagBadge();home()}
 private fun paymentOwnerMatches():Boolean{val owner=pref.getString("pending_checkout_user_id",null)?:pref.getString("checkout_user_id",null);val user=currentUserId();return hasSession()&&owner!=null&&owner==user}
 private fun openPendingCheckout(){if(!paymentOwnerMatches()){Toast.makeText(this,"Sign in with the account that started this checkout.",Toast.LENGTH_LONG).show();return};val url=pref.getString("pending_checkout_url",null)?:return;if(!validCheckoutUrl(url)){Toast.makeText(this,"Checkout address could not be verified. Your bag is safe.",Toast.LENGTH_LONG).show();return};when(CheckoutBrowser.open(this,url)){CheckoutBrowser.OpenResult.CUSTOM_TAB,CheckoutBrowser.OpenResult.DEFAULT_BROWSER->Unit;CheckoutBrowser.OpenResult.INVALID_URL->Toast.makeText(this,"Checkout address could not be verified. Your bag is saved.",Toast.LENGTH_LONG).show();CheckoutBrowser.OpenResult.NO_BROWSER_AVAILABLE->Toast.makeText(this,"No secure browser is available. Your bag is saved.",Toast.LENGTH_LONG).show()}}
 private fun checkPendingPayment(showPending:Boolean,resumeCheckout:Boolean=false){
  val id=pref.getString("pending_checkout_order",null)?:return
  if(!paymentOwnerMatches()){if(showPending)Toast.makeText(this,"Sign in with the account that started this checkout.",Toast.LENGTH_LONG).show();return}
  if(paymentCheckBusy||(System.currentTimeMillis()-lastPaymentPoll<1500&&!resumeCheckout))return
  val session=currentSession()?:run{if(showPending)auth();return};val generation=session.generation
  paymentCheckBusy=true;lastPaymentPoll=System.currentTimeMillis()
  ex.execute{val previous=requestTicketLocal.get();try{authSession.assertCurrentGeneration(generation);requestTicketLocal.set(generation);val status=JSONObject(apiReq("/v1/checkout/$id")).optString("status");authSession.assertCurrentGeneration(generation);requestTicketLocal.remove();runOnUiThread{try{authSession.assertCurrentGeneration(generation)}catch(e:Exception){paymentCheckBusy=false;showRequestError(e);return@runOnUiThread};paymentCheckBusy=false;when(status){"paid"->finishPaidPayment();"expired","failed"->{clearPaymentMarkers();if(showPending)Toast.makeText(this,"Checkout $status. Your bag is safe; continue to pickup to try again.",Toast.LENGTH_LONG).show()};"refunded"->{clearPaymentMarkers();if(showPending)Toast.makeText(this,"This checkout was refunded. Your bag is safe.",Toast.LENGTH_LONG).show()};"pending"->{if(resumeCheckout)openPendingCheckout()else if(showPending)Toast.makeText(this,"Payment is still processing. Your bag is safe.",Toast.LENGTH_LONG).show()};else->{if(showPending)Toast.makeText(this,"Payment status is still being confirmed.",Toast.LENGTH_LONG).show()}}}}catch(e:Exception){requestTicketLocal.remove();runOnUiThread{paymentCheckBusy=false;if(e is CenaSessionExpiredException)showRequestError(e)else if(showPending)Toast.makeText(this,e.message?:"Could not check payment yet.",Toast.LENGTH_LONG).show()}}finally{if(previous!=null)requestTicketLocal.set(previous)}}
}private fun cancelPendingCheckout(){val id=pref.getString("pending_checkout_order",null)?:return;if(!paymentOwnerMatches()){Toast.makeText(this,"Sign in with the account that started this checkout.",Toast.LENGTH_LONG).show();return};go({apiReq("/v1/checkout/$id","DELETE")}){val status=JSONObject(it).optString("status");when(status){"expired"->{clearPaymentMarkers();Toast.makeText(this,"Checkout canceled. Your bag is still here.",Toast.LENGTH_LONG).show();bagScreen()};"refunded"->{clearPaymentMarkers();Toast.makeText(this,"This checkout was refunded. Your bag is safe.",Toast.LENGTH_LONG).show();bagScreen()};"paid"->finishPaidPayment();else->Toast.makeText(this,"Checkout is still being confirmed. Your bag is safe.",Toast.LENGTH_LONG).show()}}}
 private fun submitCheckoutRequest(request:JSONObject){if(paymentRequestInFlight)return;paymentRequestInFlight=true;val requestScreen=body;val owner=pref.getString("checkout_user_id",null);val user=currentUserId();if(owner==null||owner!=user){paymentRequestInFlight=false;Toast.makeText(this,"Sign in with the account that started this checkout.",Toast.LENGTH_LONG).show();return};go({try{val response=JSONObject(apiReq("/v1/checkout","POST",request));response.put("_checkout_owner",owner);response.toString()}catch(e:Exception){val http=e as? CenaApiHttpException;val status=if(http?.statusCode==409)runCatching{JSONObject(http.responseBody).optString("status")}.getOrDefault("")else "";if(status=="expired"||status=="failed"||status=="refunded"){clearPaymentMarkers();val message=if(status=="refunded")"The previous checkout was refunded. Your bag is safe; no new charge was made." else "The previous checkout $status. Your bag is safe; tap Pay securely in Cena to start again.";throw Exception(message)};val rejection=if(http?.statusCode==422)runCatching{JSONObject(http.responseBody)}.getOrNull()else null;val code=if(rejection!=null&&rejection.has("code")&&!rejection.isNull("code"))rejection.optString("code")else "";if(code in recoverableCheckoutCodes){clearPaymentMarkers();val promo=if(request.has("promo_code")&&!request.isNull("promo_code"))request.optString("promo_code")else null;throw CheckoutRecoveryException(code,checkoutRejectionMessage(code),promo,owner,requestScreen)};val stalePrice=if(http?.statusCode==409)runCatching{JSONObject(http.responseBody).optString("error")}.getOrDefault("").equals("checkout price changed; request a new quote",true)else false;if(stalePrice){clearPaymentMarkers();activePromoCode=null;expectedAmountCents=null;throw Exception("The pickup total changed. Review your order and request a fresh quote before paying.")};throw e}}){response->paymentRequestInFlight=false;val payment=JSONObject(response);val id=payment.getString("order_id");val url=payment.optString("checkout_url");val editor=pref.edit().putString("pending_checkout_order",id).putString("pending_checkout_user_id",payment.optString("_checkout_owner"));if(validCheckoutUrl(url))editor.putString("pending_checkout_url",url);editor.commit();if(payment.optString("status")=="paid")checkPendingPayment(true)else if(validCheckoutUrl(url))openPendingCheckout()else Toast.makeText(this,"Your order is saved, but the secure checkout address could not be verified. Your bag is safe.",Toast.LENGTH_LONG).show()}}
 private fun startCheckout(){
  if(paymentRequestInFlight)return
  if(bag.isEmpty()||slot==null){Toast.makeText(this,"Add meal kits and choose a pickup time first.",Toast.LENGTH_SHORT).show();return}
  val session=currentSession();if(session==null){auth();return};val owner=session.userId?:run{auth();return}
  val pending=pref.getString("pending_checkout_order",null);if(pending!=null){checkPendingPayment(true,true);return}
  val savedRequest=pref.getString("checkout_request",null);if(savedRequest!=null){if(pref.getString("checkout_user_id",null)!=owner){Toast.makeText(this,"Sign in with the account that started this checkout.",Toast.LENGTH_LONG).show();return};submitCheckoutRequest(JSONObject(savedRequest));return}
  val amount=expectedAmountCents;if(amount==null){Toast.makeText(this,"Confirm the current pickup total before payment.",Toast.LENGTH_LONG).show();return}
  val restaurantSnapshot=bag.first().restaurant;val slotSnapshot=slot!!;val lines=bag.map{BagLine(it.restaurant,it.meal,it.quantity)}
  val items=JSONArray();lines.forEach{items.put(JSONObject().put("item_id",it.meal.getString("id")).put("quantity",it.quantity))}
  val key=java.util.UUID.randomUUID().toString();val curbside=curbsideForCheckout;val vehicle=if(curbside)JSONObject().put("make",curbMake).put("model",curbModel).put("color",curbColor)else JSONObject()
  val request=JSONObject().put("p_restaurant_id",restaurantSnapshot.getString("id")).put("p_slot_id",slotSnapshot.getString("id")).put("p_idempotency_key",key).put("p_pickup_mode",if(curbside)"curbside" else "counter").put("p_vehicle",vehicle).put("p_items",items).put("expected_amount_cents",amount)
  activePromoCode?.let{request.put("promo_code",it)}
  pref.edit().putString("checkout_user_id",owner).putString("checkout_idempotency_key",key).putString("checkout_request",request.toString()).commit();paymentRequestInFlight=true;persistBag()
  go({authSession.assertCurrentGeneration(session.generation);val user=JSONObject(req("/auth/v1/user"));if(user.optString("id")!=owner)throw CenaSessionExpiredException();request.toString()}){serialized->paymentRequestInFlight=false;submitCheckoutRequest(JSONObject(serialized))}
} private fun addToBag(r:JSONObject,m:JSONObject){
  val owner=currentUserId()?:"guest";val savedOwner=pref.getString("bag_user_id",null)
  if(savedOwner!=null&&savedOwner!="guest"&&savedOwner!=owner){Toast.makeText(this,"Sign in with the account that owns this saved bag.",Toast.LENGTH_LONG).show();auth();return}
  if(paymentRequestInFlight||pref.getString("pending_checkout_order",null)!=null||pref.getString("checkout_request",null)!=null){Toast.makeText(this,"Finish or cancel the current checkout before changing your bag.",Toast.LENGTH_LONG).show();return}
  val rid=r.optString("id");val current=bag.firstOrNull()?.restaurant?.optString("id")
