private fun locationDialog(){val input=EditText(this).apply{hint="Street address, city, state";setSingleLine();setText(manualLocation?:"")};lateinit var dialog:AlertDialog;val content=LinearLayout(this).apply{orientation=1;setPadding(24,8,24,0);addView(input);addView(Button(this@MainActivity).apply{text="Use approximate device location";setOnClickListener{dialog.dismiss();requestApproxLocation()}});addView(Button(this@MainActivity).apply{text="Use San Francisco pickup area";setOnClickListener{dialog.dismiss();usingDeviceLocation=false;manualLocation=null;originLat=sfLat;originLon=sfLon;catalog()}})};dialog=AlertDialog.Builder(this).setTitle("Pickup location").setView(content).setPositiveButton("Find address",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener{dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener{val address=input.text.toString().trim();if(address.isNotBlank()){dialog.dismiss();resolveAddress(address)}else input.error="Enter an address"}};dialog.show()}
