 private fun addCuisinePage(categories:JSONArray){for(i in 0 until categories.length()){val cat=categories.optJSONObject(i)?:continue;val restaurants=cat.optJSONArray("restaurants")?:JSONArray();if(restaurants.length()==0)continue;section(cat.optString("name","More nearby"));addRestaurantRail(restaurants)}} private fun menu(){val r=restaurant!!;go({req("/rest/v1/catalog_items?select=id,name,description,price_cents,prepared_meal_total_cents,image_key&restaurant_id=eq.${r.getString("id")}&active=eq.true&published_at=not.is.null&order=name")}){val a=JSONArray(it);base();profileControl();title(r.optString("name"));text(r.optString("address"));for(i in 0 until a.length()){val m=a.getJSONObject(i);val photo=ImageView(this).apply{layoutParams=LinearLayout.LayoutParams(-1,(190*resources.displayMetrics.density).toInt());scaleType=ImageView.ScaleType.CENTER_CROP;setImageResource(imageResource(m.optString("image_key","mediterranean")))};body.addView(photo);button("${m.optString("name")}\n${m.optString("description")}\nMeal kit · $${"%.2f".format(m.optInt("price_cents")/100.0)}"){addToBag(r,m)};preparedPriceView(m)?.let{body.addView(it)}};button("Back to kitchens"){catalog()}}}
 private fun loadSlots(){val r=restaurant!!;go({req("/rest/v1/pickup_slots?select=id,starts_at,ends_at,cutoff_at&restaurant_id=eq.${r.getString("id")}&active=eq.true&starts_at=gt.${java.time.Instant.now().plusSeconds(32*60)}&cutoff_at=gt.${java.time.Instant.now()}&order=starts_at")}){val a=JSONArray(it);base();title("Choose pickup day");text("Payment requires a pickup window at least 32 minutes away.");if(a.length()==0)text("No eligible pickup windows remain. Choose another day or check again later.");val zone=runCatching{java.time.ZoneId.of(r.optString("timezone").takeIf{it.isNotBlank()&&it!="null"}?:"America/Los_Angeles")}.getOrDefault(java.time.ZoneId.of("America/Los_Angeles"));val days=(0 until a.length()).map{java.time.Instant.parse(a.getJSONObject(it).optString("starts_at")).atZone(zone).toLocalDate().toString()}.distinct();for(day in days)button(java.time.LocalDate.parse(day).let{it.dayOfWeek.name.lowercase().replaceFirstChar(Char::uppercase)+", "+it.month.name.lowercase().replaceFirstChar(Char::uppercase)+" "+it.dayOfMonth}){showTimes(day,a)};button("Back to menu"){menu()}}}
private fun showTimes(day:String,a:JSONArray){
  val zone=runCatching{java.time.ZoneId.of(restaurant?.optString("timezone")?.takeIf{it.isNotBlank()&&it!="null"}?:"America/Los_Angeles")}.getOrDefault(java.time.ZoneId.of("America/Los_Angeles"))
  val pickupToday=day==java.time.LocalDate.now(zone).toString()
  base();title(java.time.LocalDate.parse(day).let{it.dayOfWeek.name.lowercase().replaceFirstChar(Char::uppercase)+", "+it.month.name.lowercase().replaceFirstChar(Char::uppercase)+" "+it.dayOfMonth})
  for(i in 0 until a.length()){
    val sl=a.getJSONObject(i);val starts=java.time.Instant.parse(sl.optString("starts_at"))
    if(starts.atZone(zone).toLocalDate().toString()!=day)continue
    val cutoff=java.time.Instant.parse(sl.optString("cutoff_at")).toEpochMilli()
    val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(12,10,12,10);background=GradientDrawable().apply{setColor(paper);cornerRadius=14*resources.displayMetrics.density;setStroke((1*resources.displayMetrics.density).toInt(),rose)};layoutParams=LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=(10*resources.displayMetrics.density).toInt()}}
    row.addView(TextView(this).apply{text=starts.atZone(zone).format(java.time.format.DateTimeFormatter.ofPattern("HH:mm",java.util.Locale.getDefault()));textSize=19f;setTextColor(wine);typeface=android.graphics.Typeface.DEFAULT_BOLD;layoutParams=LinearLayout.LayoutParams(0,-2,1f)})
    val badge=TextView(this).apply{setTextColor(Color.rgb(28,112,61));textSize=13f;setPadding(10,7,10,7);background=GradientDrawable().apply{setColor(Color.rgb(239,249,240));cornerRadius=12*resources.displayMetrics.density;setStroke((1*resources.displayMetrics.density).toInt(),Color.rgb(53,142,83))}}
    row.addView(badge)
    val tick=object:Runnable{override fun run(){val left=(cutoff-System.currentTimeMillis()).coerceAtLeast(0);val sec=left/1000;val label=if(pickupToday)"Order cutoff for pickup today" else "Order cutoff";badge.text="$label · %02d:%02d:%02d".format(sec/3600,(sec%3600)/60,sec%60);row.isEnabled=left>0;badge.alpha=if(left>0)1f else .55f;if(left>0)mainHandler.postDelayed(this,1000)}}
    countdownTasks.add(tick);tick.run();row.setOnClickListener{slot=sl;checkout()};body.addView(row)
  }
  button("Choose another day"){loadSlots()}
}
private fun applyPromoAndContinue(code:String?){
  if(!hasSession()){pendingQuotePromo=code;resumeQuoteAfterAuth=true;auth();return}
  checkoutPromoInput?.setText(code.orEmpty())
  if(bag.isEmpty()||slot==null){Toast.makeText(this,"Choose a pickup time before payment.",Toast.LENGTH_LONG).show();return}
  val items=JSONArray();for(line in bag)items.put(JSONObject().put("item_id",line.meal.getString("id")).put("quantity",line.quantity))
  val request=JSONObject().put("p_restaurant_id",bag.first().restaurant.getString("id")).put("p_slot_id",slot!!.optString("id")).put("p_items",items)
  code?.takeIf{it.isNotBlank()}?.let{request.put("promo_code",it)}
  val requestOwner=currentUserId()?:run{auth();return}
  val requestSlot=slot!!.optString("id")
  val checkoutScreen=body
  ex.execute {
    val raw=try {
      apiReq("/v1/checkout/quote","POST",request)
    } catch(error:Exception) {
      val http=error as? CenaApiHttpException
      val payload=runCatching { JSONObject(http?.responseBody?:error.message.orEmpty()) }.getOrNull()
      runOnUiThread {
        if(body!==checkoutScreen||currentUserId()!=requestOwner||slot?.optString("id")!=requestSlot)return@runOnUiThread
        activePromoCode=null;expectedAmountCents=null
        val rejectionCode=payload?.optString("code")?.takeIf{http?.statusCode==422&&it in recoverableCheckoutCodes}
        if(rejectionCode!=null)showCheckoutRecovery(rejectionCode,checkoutRejectionMessage(rejectionCode),code,requestOwner,checkoutScreen)
        else AlertDialog.Builder(this).setTitle("Couldn’t check your total").setMessage("Couldn’t check your pickup total. Please try again.").setPositiveButton("OK",null).show()
      }
      return@execute
    }
    runOnUiThread {
    if(body!==checkoutScreen||currentUserId()!=requestOwner||slot?.optString("id")!=requestSlot)return@runOnUiThread
      val quote=runCatching { JSONObject(raw) }.getOrNull() ?: JSONObject()
      val subtotal=quote.optInt("subtotal_cents",-1)
      val discount=quote.optInt("discount_cents",-1)
      val total=quote.optInt("amount_cents",-1)
      val currency=quote.optString("currency").uppercase(java.util.Locale.ROOT)
      if(subtotal<0||discount<0||total<0||discount>subtotal||total!=subtotal-discount||currency!="USD") {
        Toast.makeText(this,"Cena returned an incomplete price quote. Try again.",Toast.LENGTH_LONG).show()
        activePromoCode=null
        expectedAmountCents=null
        return@runOnUiThread
      }
      val serverCode=if(quote.isNull("promo_code"))null else quote.optString("promo_code").takeIf{it.isNotBlank()}
      val requestedCode=code?.trim()?.uppercase(java.util.Locale.ROOT)?.takeIf{it.isNotBlank()}
      if(serverCode!=requestedCode||(serverCode==null&&discount!=0)||(serverCode!=null&&discount<=0)) {
        activePromoCode=null
        expectedAmountCents=null
        Toast.makeText(this,"The discount and quote did not match. Try again.",Toast.LENGTH_LONG).show()
        return@runOnUiThread
      }
      activePromoCode=serverCode
      expectedAmountCents=total
      val discountLine=if(discount>0)"Discount · −$${"%.2f".format(discount/100.0)}\n" else ""
      AlertDialog.Builder(this)
        .setTitle(if(serverCode!=null)"Promo code applied" else "Confirm pickup total")
        .setMessage("Kit subtotal · $${"%.2f".format(subtotal/100.0)}\n${discountLine}Due today · $${"%.2f".format(total/100.0)} $currency\n\nCena will recheck this amount when your order is placed.")
        .setNegativeButton("Review order",null)
        .setPositiveButton("Continue to secure payment"){_,_->startCheckout()}
        .show()
    }
  }
}
private fun pickupSummary():String {
  val startsAt=slot?.optString("starts_at") ?: return "time selected"
  val timezone=runCatching {
    java.time.ZoneId.of(restaurant?.optString("timezone","America/Los_Angeles") ?: "America/Los_Angeles")
  }.getOrDefault(java.time.ZoneId.of("America/Los_Angeles"))
  return runCatching {
    java.time.Instant.parse(startsAt).atZone(timezone).format(
      java.time.format.DateTimeFormatter.ofPattern("EEE, MMM d 'at' h:mm a",java.util.Locale.getDefault())
    )
  }.getOrDefault("time selected")
}
private fun checkout(){if(bag.isEmpty()){bagScreen();return};restaurant=bag.first().restaurant;base();profileControl();title("Pickup details");text(restaurant?.optString("name")?:"");for(line in bag)text("${line.quantity} × ${line.meal.optString("name")} · $${"%.2f".format(line.meal.optInt("price_cents")*line.quantity/100.0)}");val subtotal=bag.sumOf{it.meal.optInt("price_cents",0)*it.quantity};title("Kit subtotal · $${"%.2f".format(subtotal/100.0)}",18f);text("Pickup ${pickupSummary()}");val curbAllowed=restaurant?.optBoolean("curbside_enabled",false)==true;curbsideForCheckout=curbsideForCheckout&&curbAllowed;val curb=CheckBox(this).apply{text="Curbside pickup";isChecked=curbsideForCheckout;setTextColor(wine)};var vehicleInputs=listOf<EditText>();if(curbAllowed){body.addView(curb);val brand=field("Vehicle make");brand.setText(curbMake);val model=field("Vehicle model");model.setText(curbModel);val color=field("Vehicle color");color.setText(curbColor);vehicleInputs=listOf(brand,model,color);vehicleInputs.forEach{it.visibility=if(curb.isChecked)View.VISIBLE else View.GONE};curb.setOnCheckedChangeListener{_,checked->curbsideForCheckout=checked;vehicleInputs.forEach{it.visibility=if(checked)View.VISIBLE else View.GONE}}};val promo=field("Promo code (optional)");promo.isSingleLine=true;checkoutPromoInput=promo;button("Pay securely in Cena"){curbsideForCheckout=curbAllowed&&curb.isChecked;if(curbsideForCheckout&&vehicleInputs.size==3){curbMake=vehicleInputs[0].text.toString();curbModel=vehicleInputs[1].text.toString();curbColor=vehicleInputs[2].text.toString()};val code=promo.text.toString().trim().takeIf{it.isNotBlank()};pendingQuotePromo=code;if(!hasSession()){resumeQuoteAfterAuth=true;auth()}else applyPromoAndContinue(code)};button("Back to pickup times"){loadSlots()}}
 private fun orders(){go({req("/rest/v1/orders?select=id,status,payment_status,subtotal_cents,total_cents,pickup_starts_at,restaurants(name)&order=created_at.desc&limit=20")}){val a=JSONArray(it);base();title("My reservations");if(a.length()==0)text("No reservations yet.");for(i in 0 until a.length()){val o=a.getJSONObject(i);val payment=o.optString("payment_status").lowercase();val amount=o.optInt("total_cents",o.optInt("subtotal_cents",0));val amountLabel=when(payment){"paid"->"Paid";"refunded"->"Refunded";"pending"->"Due";"failed","cancelled"->"Not charged";else->"Order total"};text("${o.optJSONObject("restaurants")?.optString("name")} · $amountLabel $${"%.2f".format(amount/100.0)}\n${o.optString("status")} · ${o.optString("pickup_starts_at").replace("T"," · ").take(17)}")};button("Back"){home()}}}
}
